    r"|traded\s+on\s+.+?\s+under\s+the\s+ticker\s+symbol",
    re.IGNORECASE,
)
_EXCHANGE_RE = re.compile(
    r"\b(?:"
    r"New\s+York\s+Stock\s+Exchange(?:,\s*Inc\.)?"
    r"|Chicago\s+Stock\s+Exchange(?:,\s*Inc\.)?"
    r"|The\s+Nasdaq\s+Stock\s+Market\s+LLC"
