    r"|NYSE(?:\s+American|\s+Arca)?"
    r")\b",
    re.IGNORECASE,
)
_SYMBOL_HINT_RE = re.compile(
    r"\[\s*(?:NYSE|Nasdaq)\s*:\s*[A-Z][A-Z0-9.\-]{0,12}\s*\]"
    r"|symbol\s+[\"“']?[A-Z][A-Z0-9.\-]{0,12}[\"”']?"
    r"|ticker\s+symbol\s+(?:is\s+)?[\"“']?[A-Z][A-Z0-9.\-]{0,12}[\"”']?",
