                    r"|the\s+company'?s\s+common\s+stock"
                    r"|our\s+common\s+stock"
                    r"|[A-Z][A-Za-z&.,' ]+\[(?:NYSE|Nasdaq)",
                    cleaned[max(0, start - 180) :],
                    re.IGNORECASE,
